#!/usr/bin/env python3
"""Randomised cross-check of main.solve against a brute force ground truth."""
import itertools
import json
import random
import sys

sys.path.insert(0, "/app")
from main import solve
from public_contract import valid_history

KEYS = list("abcdef")
VALS = list(range(-9, 10))


def brute(request):
    ids = [t["id"] for t in request["transactions"]]
    for perm in itertools.permutations(ids):
        try:
            if valid_history(request, list(perm)):
                return list(perm)
        except Exception:
            return None  # malformed for every order
    return None


def gen_op(state, rng, keys, weights):
    kind = rng.choices(["get", "put", "del", "cas", "scan"], weights=weights)[0]
    k = rng.choice(keys)
    if kind == "get":
        return ["get", k, state.get(k)]
    if kind == "put":
        v = rng.choice(VALS)
        state[k] = v
        return ["put", k, v]
    if kind == "del":
        state.pop(k, None)
        return ["del", k]
    if kind == "cas":
        if rng.random() < 0.65:
            old, ok = state.get(k), True
        else:
            old, ok = rng.choice(VALS + [None]), None
        new = rng.choice(VALS + [None])
        if ok is None:
            ok = state.get(k) == old
        if ok:
            if new is None:
                state.pop(k, None)
            else:
                state[k] = new
        return ["cas", k, old, new, ok]
    lo = rng.choice(keys)
    hi = rng.choice(keys)
    while not lo < hi:
        hi = rng.choice(keys)
    pairs = sorted([[kk, vv] for kk, vv in state.items() if lo <= kk < hi])
    return ["scan", lo, hi, [list(p) for p in pairs]]


def gen_request(rng, nmax=6, weights=(3, 3, 2, 3, 2), tight=None):
    nkeys = rng.randint(1, 6)
    keys = sorted(rng.sample(KEYS, nkeys))
    initial = {k: rng.choice(VALS) for k in keys if rng.random() < 0.5}
    n = rng.randint(0, nmax)
    ids = ["t%d" % i for i in range(n)]
    serial = ids[:]
    rng.shuffle(serial)
    tight = rng.random() < 0.5 if tight is None else tight
    state = dict(initial)
    txs = []
    for pos, tid in enumerate(serial):
        p = 3 * pos + rng.randint(0, 2)
        if tight:
            start, end = p, p + 1
        else:
            start = p - rng.randint(0, 3)
            end = p + rng.randint(1, 4)
            if not start < end:
                start, end = p, p + 1
        ops = [gen_op(state, rng, keys, weights) for _ in range(rng.randint(1, 5))]
        txs.append({"id": tid, "start": start, "end": end, "ops": ops})
    rng.shuffle(txs)
    return {"initial": initial, "final": dict(state), "transactions": txs}


def mutate(request, rng):
    request = json.loads(json.dumps(request))
    r = rng.random()
    if r < 0.4 and request["transactions"]:
        t = rng.choice(request["transactions"])
        op = rng.choice(t["ops"])
        if op[0] == "get":
            op[2] = None if op[2] is not None else rng.choice(VALS)
        elif op[0] == "put":
            op[2] = rng.choice(VALS)
        elif op[0] == "cas":
            i = rng.randint(2, 4)
            op[i] = (not op[i]) if i == 4 else rng.choice(VALS + [None])
        elif op[0] == "scan":
            if op[3] and rng.random() < 0.7:
                rng.shuffle(op[3])
            else:
                op[3] = []
        elif op[0] == "del":
            op[1] = rng.choice(KEYS)
    elif r < 0.8:
        final = request["final"]
        if final and rng.random() < 0.5:
            k = rng.choice(list(final))
            if rng.random() < 0.5:
                del final[k]
            else:
                final[k] = rng.choice(VALS)
        else:
            request["final"][rng.choice(KEYS)] = rng.choice(VALS)
    elif request["transactions"]:
        t = rng.choice(request["transactions"])
        t["start"], t["end"] = t["end"], t["start"]
    return request


def run(seed_start=0, count=2000, nmax=6, mutate_p=0.5, weights=(3, 3, 2, 3, 2)):
    rng = random.Random(seed_start)
    sat = unsat = 0
    for it in range(count):
        req = gen_request(rng, nmax=nmax, weights=weights)
